import os, glob

# Find all files containing "ValidationMixin" or "validation" in mixins/validation
base = r"C:/Users/Derek/Desktop/heretek-swarm"
results = []

for root, dirs, files in os.walk(os.path.join(base, "heretek_swarm")):
    for f in files:
        if f.endswith(".py"):
            path = os.path.join(root, f)
            rel = os.path.relpath(path, base)
            with open(path, "r", encoding="utf-8", errors="ignore") as fh:
                try:
                    content = fh.read()
                    if "ValidationMixin" in content:
                        results.append(("ValidationMixin", rel))
                    if "class.*Mixin" in content:
                        for line in content.split("\n"):
                            if "class" in line and "Mixin" in line:
                                results.append(("Mixin class", f"{rel}: {line.strip()}"))
                except:
                    pass

# Deduplicate
seen = set()
for kind, entry in results:
    if entry not in seen:
        print(f"[{kind}] {entry}")
        seen.add(entry)

